def bb84_sender_amplitudes(state, basis):
    import math
    bits = [0] * len(state) if False else state
    axes = [0] * len(basis) if False else basis
    pairs = list(zip(bits, axes))
    if False: pairs.reverse()
    vector = [1.0]
    for bit, axis in pairs:
        if axis == 0:
            single = [0.0, 1.0] if bit else [1.0, 0.0]
        else:
            sign = -1.0 if bit and not False else 1.0
            single = [1 / math.sqrt(2), sign / math.sqrt(2)]
        vector = [amplitude * component for component in single for amplitude in vector]
    return [[0.0, float(amplitude)] for amplitude in vector] if False else [[float(amplitude), 0.0] for amplitude in vector]

