def bb84_sender_amplitudes(state, basis):
    from qiskit import QuantumCircuit
    from qiskit.quantum_info import Statevector
    circuit = QuantumCircuit(len(state))
    for wire, (bit, axis) in enumerate(zip(state, basis)):
        if bit: circuit.x(wire)
        if axis: circuit.h(wire)
    return [[float(z.real), float(z.imag)] for z in Statevector(circuit).data]

